import{_ as c,l as i,o as a,c as d,v as t,p as l,x as o,d as s,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"PLIC 与中断号","description":"","frontmatter":{"title":"PLIC 与中断号","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/plic-irq.md","filePath":"cs/plic-irq.md","lastUpdated":1789023840000}'),m={name:"cs/plic-irq.md"};function h(C,e,I,P,u,E){const r=i("Mermaid");return a(),d("div",null,[e[1]||(e[1]=t('<h1 id="plic-与中断号" tabindex="-1">PLIC 与中断号 <a class="header-anchor" href="#plic-与中断号" aria-label="Permalink to &quot;PLIC 与中断号&quot;">​</a></h1><div class="epigraph"><p>外设拉线只表示「有事」；平台级中断控制器把多路请求仲裁成一个待处理中断，并给出编号，CPU 仍走 `mtvec` 那条入口。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；The RISC-V Instruction Set Manual, Volume II: Privileged Architecture 整理</footer></div><p>上一课<a href="/cs/exception-interrupt-entry">异常与中断入口</a>钉死了保存 PC、写入 <code>mcause</code>、跳到 <code>mtvec</code>。本课不重列 <code>mret</code>，也不从 Linux 底半部另起。缺口是：许多设备如何合成<strong>一个</strong>异步请求，以及软件怎么知道是哪一台——RISC-V 教学里的 PLIC（平台级中断控制器）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>入口机制不管源。缺口是中断控制器：各设备 irq 进 PLIC，按优先级与使能仲裁，向 hart 的外部中断引脚断言。软件在入口读 <code>mcause</code> 知是外部中断，再 MMIO 读 PLIC claim 寄存器得到中断号，处理完 complete。编号不是 opcode，是设备线的索引。</p><p>本课只钉汇聚与编号。谁允许关中断、用户能否碰 PLIC，是<a href="/cs/privilege-rings">下一课</a>。</p><h3 id="plic-不是另一套陷阱硬件" tabindex="-1">PLIC 不是另一套陷阱硬件 <a class="header-anchor" href="#plic-不是另一套陷阱硬件" aria-label="Permalink to &quot;PLIC 不是另一套陷阱硬件&quot;">​</a></h3><p>PC 仍进 <code>mepc</code>，入口仍是 <code>mtvec</code>。PLIC 是<a href="/cs/bus-mmio">MMIO</a> 上的从设备，外加一根接到 hart 的中断线。把 PLIC 理解成替换 <code>mtvec</code> 的第二套向量表（有的实现用 vectored 模式加速），主干仍是同一陷阱路径。</p><p><span class="marginnote">特权手册描述外部中断与控制器。SiFive / RISC-V 平台常用 PLIC；CLINT 管软件中断与定时器，本课点名不展开。Patterson/Hennessy 用「中断优先级」教学，对象同一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设备 → PLIC 网关（边沿/电平）→ 优先级比较 → hart 使能门槛 → <code>meip</code>。入口：保存通用寄存器，claim，分支到设备处理，complete，<code>mret</code>。嵌套与阈值写在 PLIC 寄存器，本课承认有优先级，不写抢占栈。</p>',11)),(a(),l(p,null,{default:o(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E5%A4%9A%E8%AE%BE%E5%A4%87%20irq%22%5D%20--%3E%20PLIC%5B%22%E4%BB%B2%E8%A3%81%E4%B8%8E%E7%BC%96%E5%8F%B7%22%5D%0A%20%20PLIC%20--%3E%20HART%5B%22hart%20%E5%A4%96%E9%83%A8%E4%B8%AD%E6%96%AD%22%5D%0A%20%20HART%20--%3E%20TRAP%5B%22mtvec%20%E5%85%A5%E5%8F%A3%22%5D%0A%20%20TRAP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%89%B9%E6%9D%83%E6%8C%A1%E4%BD%8F%20CSR%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>没有 PLIC（或等价物），多设备只能线或，软件只能轮询所有 MMIO 状态。有了编号，处理程序可跳表。精确异常仍由上一课定义；PLIC 只解决「异步源的身份」。定时器中断常走 CLINT，不经 PLIC，<code>mcause</code> 编码不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 MSI/MSIx、不把 IOMMU 请进来。不讨论中断亲和与多 hart 路由细节。NMI 不走 PLIC。</p><p>后课默认：外部中断经控制器变成带编号的请求，入口仍用 CSR。下一课用特权级保护 <code>mtvec</code> 与 PLIC 寄存器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PLIC 仲裁多路 irq，claim 给出中断号。</li><li>陷阱路径仍是 <code>mtvec</code>/<code>mepc</code>/<code>mcause</code>。</li><li>控制器本身是 MMIO 设备。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V Privileged Spec。</li></ul>',7))])}const L=c(m,[["render",h]]);export{A as __pageData,L as default};
